class Solution {
public:
    vector<int> minSubsequence(vector<int>& nums) {
        sort(nums.begin(), nums.end(), greater<int>());
        int remaining = accumulate(nums.begin(), nums.end(), 0), taken = 0;
        vector<int> ans;
        for (int x : nums) {
            ans.push_back(x);
            taken += x;
            remaining -= x;
            if (taken > remaining) break;
        }
        return ans;
    }
};
